  tuningPotential: [ { stage: "Stage 1", power: "150 - 155 hp", notes: "Safe and highly recommended ECU remap. Transforms the car for daily driving.", zeroToHundred: "7.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "165 - 170 hp", notes: "Requires a high-flow downpipe. The small stock turbo runs out of flow here.", zeroToHundred: "7.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "190 - 200 hp", notes: "Requires an IS12 or Hybrid Turbo upgrade. Upgraded clutch is mandatory.", zeroToHundred: "6.5s", hundredToTwoHundred: "18.5s" } ],
  tuningGraphData: { stock: { hp: 125, nm: 200 }, stage1: { hp: 155, nm: 250 }, stage2: { hp: 170, nm: 270 }, stage3: { hp: 200, nm: 300 } },
  InspectionChecklist: [ { id: "water_pump_leak_ea211", category: "Cooling", question: "Is there pink/white crust on the right side of the engine block?", howToCheck: "Look under the intake manifold on the transmission side. The plastic water pump housing warps.", costUSD: 600, costEUR: 550, severity: "HIGH" }, { id: "turbo_actuator_epc", category: "Engine", question: "Does the EPC light illuminate during hard acceleration?", howToCheck: "The electric wastegate actuator rod seizes. Scan for OBD code P334A.", costUSD: 450, costEUR: 400, severity: "CRITICAL" }, { id: "dsg_clutch_judder", category: "Transmission", question: "Automatic: Does the car judder or shake on gentle takeoff?", howToCheck: "Drive very slowly in D mode. If it shakes, the dry clutch packs are worn out.", costUSD: 1500, costEUR: 1200, severity: "CRITICAL" }, { id: "clutch_slip_manual", category: "Transmission", question: "Manual: Does the engine RPM rise sharply without the car accelerating?", howToCheck: "Put the car in 4th gear at 40 km/h and floor the throttle.", costUSD: 800, costEUR: 700, severity: "HIGH" }, { id: "idle_roughness", category: "Engine", question: "Is the idle noticeably rough or fluctuating on a cold start?", howToCheck: "Sit in the car with AC off. Shaking indicates carbon buildup on intake valves.", costUSD: 400, costEUR: 350, severity: "MEDIUM" }, { id: "coolant_level_internal", category: "Cooling", question: "Is the coolant level below MIN in the expansion tank?", howToCheck: "The EA211 has an internal water-to-air intercooler. If it leaks internally, the engine burns the coolant.", costUSD: 100, costEUR: 80, severity: "MEDIUM" }, { id: "oil_cap_mayo", category: "Engine", question: "Is there thick, yellow 'mayonnaise' under the oil cap?", howToCheck: "Unscrew the oil cap. Can indicate condensation or a failing PCV valve.", costUSD: 50, costEUR: 40, severity: "MEDIUM" }, { id: "start_stop_battery", category: "Electronics", question: "Does the Start-Stop system constantly fail to activate?", howToCheck: "Requires a healthy AGM battery. If it never stops the engine, the battery is degraded.", costUSD: 250, costEUR: 200, severity: "LOW" } ],
  model3DPath: "/images/brands/audi/A1/8X.glb", model3DScale: 0.025, model3DRotation: [0, 0, 0], model3DVerticalOffset: 0, modelForwardDir: -1,
  manualLightPositions: { headlights: { x: 0.55, y: -0.13, z: 1.7 }, taillights: { x: 0.56, y: -0.01, z: -1.71 } }, customLightNames: { headlights: ["head_lamp_0-3"], taillights: ["rear_lamp_0-1"], drllight: ["head_lamp_0-2"] },
  riskRating: 3,
  author: "Audi A1 Clubsport Quattro (https://skfb.ly/p9Cz7) by Mona x Supercars is licensed under Creative Commons Attribution (http://creativecommons.org/licenses/by/4.0/).", drivingExperience: "The CZDD (EA211) transforms the character of the A1. The aluminum block is 22kg lighter than the old EA111, making the nose feel significantly sharper. The engine is vastly quieter, smoother, and revs more freely. The 125hp feels energetic, and the torque delivery is incredibly linear. The switch to a glass-fiber reinforced timing belt has entirely eliminated the mechanical anxiety associated with older models.", mechanicVerdict: "A vast improvement over the problematic EA111 generation. The EA211 architecture is exceptionally reliable. The primary issue to watch for is the thermal management module (water pump) leaking due to warped plastic housings. It is expensive to replace, but it is a predictable wear item, not catastrophic like the old chain failures. Carbon buildup is still a reality but managed slightly better. Highly recommended as a stress-free daily driver.", repairCostEstimate: "$600 - $800 / year",
  model3DHotspots: [{"label":"Timing Belt & Water Pump","x":-0.25,"y":0.15,"z":1.35,"critical":true,"details":"The EA211 architecture returned to a timing belt for better reliability and lower friction. The water pump is driven by a separate small belt on the opposite side of the engine."},{"label":"Front Brake Pads","x":0.87,"y":-0.39,"z":1.13,"critical":true,"details":"Primary stopping mechanism. Given the punchy torque delivery of the EA211, robust brake pads are essential for safe deceleration."},{"label":"Ignition Coils","x":0.0,"y":0.25,"z":1.18,"critical":false,"details":"Individual coil packs seated securely on top of the spark plugs. Highly reliable in the CZDD, but should be checked for oil fouling from a leaking valve cover."},{"label":"Air Filter Box","x":0.45,"y":0.2,"z":1.25,"critical":false,"details":"Integrated neatly into the engine bay layout. A clean filter ensures the highly efficient combustion cycle of the EA211 is not starved of oxygen."},{"label":"Integrated Exhaust Manifold","x":0.03,"y":-0.28,"z":-1.96,"critical":false,"details":"The CZDD features an exhaust manifold integrated directly into the cylinder head, allowing the engine to warm up faster and the turbocharger to spool almost instantly."}],
  engineBayHotspots: [ { x: 0.5, y: 0.5, label: "Engine Oil Fill Cap", details: "Check underneath for thick yellow/white 'mayonnaise' residue.", critical: false }, { x: 0.2, y: 0.2, label: "Engine Oil Dipstick", details: "Check oil level regularly to protect the variable oil pump and turbo.", critical: true }, { x: 0.8, y: 0.2, label: "Coolant Expansion Tank", details: "CRITICAL: Monitor this fluid level meticulously. Any drop indicates the water pump is likely leaking.", critical: true } ],
  visualTechGuide: { views: [ { id: "top_engine_view", label: "Top Engine View", imageUrl: "/images/engines/czca_top.jpg", hotspots: [ { x: 50, y: 20, title: "Airbox", details: "Integrated top-mount airbox for incredibly easy servicing." }, { x: 50, y: 80, title: "Rear Mounted Turbocharger", details: "The turbo is mounted at the very rear for better chassis weight distribution." } ] } ] }
